// Independent auditor boundary and built-bundle probe for PLAY-01.
// Uses the repository's own checker on virtual sources (no files written), then scans built outputs.
import assert from 'node:assert/strict';
import { readFileSync, readdirSync, statSync } from 'node:fs';
import { join } from 'node:path';
import { boundaryContext, checkSource } from './scripts/check-boundaries.mjs';

const ctx = boundaryContext(process.cwd());
const owner = name => ctx.owners.find(o => o.name === name);
const browserOwners = ctx.owners.filter(o => ['browser', 'public'].includes(o.scope));
assert.deepEqual(browserOwners.map(o => o.name).sort(), ['@lorcana/contracts', '@lorcana/design-system', '@lorcana/engine-lab', '@lorcana/presentation', '@lorcana/web']);
const privateTargets = ['@lorcana/db', '@lorcana/match-service', '@lorcana/engine-adapter', '@lorcana/service-runtime', 'pg', 'pg/lib/client', 'node:worker_threads', 'worker_threads', 'node:crypto'];
const relTargets = owner => [
  join(ctx.root, 'packages/db/src/match-store.ts'), join(ctx.root, 'apps/match-service/src/service.ts'), join(ctx.root, 'apps/match-service/src/engine-executor.ts'),
  join(ctx.root, 'packages/engine-adapter/src/persistence.ts'), join(ctx.root, 'packages/db/migrations/0002-match-commands.sql'),
].map(abs => require_relative(join(owner.path, 'src'), abs));
function require_relative(from, to) { const a = from.split('/'), b = to.split('/'); let i = 0; while (a[i] === b[i]) i++; return '../'.repeat(a.length - i) + b.slice(i).join('/'); }
const forms = s => [`import x from '${s}';`, `export * from '${s}';`, `const m = await import('${s}');`, `import type { X } from '${s}';`];
let refused = 0;
for (const o of browserOwners) {
  const file = join(o.path, 'src', 'audit-virtual.ts');
  for (const target of [...privateTargets, ...relTargets(o)]) for (const code of forms(target)) {
    assert.throws(() => checkSource(file, ctx, code), /Forbidden/, o.name + ' accepted ' + code);
    refused++;
  }
  // Positive control: the browser-safe policy metadata itself stays importable.
  checkSource(file, ctx, `import { isPlayerMove } from '@lorcana/contracts/player-moves';`);
}
// Server owners other than the adapter cannot reach the kernel or the Lab; match-service enters via the adapter.
let serverRefused = 0;
for (const name of ['@lorcana/match-service', '@lorcana/db', '@lorcana/api', '@lorcana/worker', '@lorcana/service-runtime']) {
  const file = join(owner(name).path, 'src', 'audit-virtual.ts');
  for (const target of ['@lorcana/vendor-engine', '@lorcana/engine-lab', join(ctx.root, 'vendor/tcg-engines/dist/kernel.js'), join(ctx.root, 'tests/play/move-policy.test.mjs')]) {
    const spec = target.startsWith('/') ? require_relative(join(owner(name).path, 'src'), target) : target;
    for (const code of forms(spec)) { assert.throws(() => checkSource(file, ctx, code), /Forbidden/, name + ' accepted ' + code); serverRefused++; }
  }
}
checkSource(join(owner('@lorcana/match-service').path, 'src', 'audit-virtual.ts'), ctx, `import { restorePrivateMatch } from '@lorcana/engine-adapter';`);
// Actual match-service sources import the kernel only through the adapter.
for (const f of readdirSync('apps/match-service/src')) {
  const text = readFileSync('apps/match-service/src/' + f, 'utf8');
  assert.equal(/@lorcana\/vendor-engine|@lorcana\/engine-lab|\/vendor\//.test(text), false, f);
}

// Built outputs.
function files(dir) { return readdirSync(dir, { withFileTypes: true }).flatMap(e => e.isDirectory() ? files(join(dir, e.name)) : [join(dir, e.name)]); }
const webFiles = files('apps/web/dist').filter(f => /\.(js|html|css|map)$/.test(f));
const labFiles = files('packages/engine-lab/dist').filter(f => f.endsWith('.js'));
const serverOnly = ['createMatchRepository', 'match.command_receipts', 'match.outbox', 'private-match-checkpoint-v1', 'restorePrivateMatch', 'createPrivateMatch', 'PERSISTENT_ENGINE_IDENTITY', 'synthetic-play01', 'match-command-intent-v1', 'transition-worker', 'pg-pool', 'pg-protocol', 'createEngineExecutor', 'lorcana_test_match', 'lorcana_local_match', 'completed-private-replay-v1', 'server-match-seed-v1'];
for (const f of [...webFiles, ...labFiles]) {
  const text = readFileSync(f, 'utf8');
  for (const s of serverOnly) assert.equal(text.includes(s), false, f + ' contains ' + s);
}
const lab = readFileSync('packages/engine-lab/dist/lab-worker.js', 'utf8');
assert.ok(lab.includes('MOVE_FORBIDDEN'), 'Lab worker lacks the policy guard');
for (const m of ['chooseWhoGoesFirst', 'moveCharacterToLocation', 'resolveEffect', 'concede']) assert.ok(lab.includes(`"${m}"`) || lab.includes(`'${m}'`), 'Lab worker lacks allowlisted ' + m);
const labIndex = readFileSync('packages/engine-lab/dist/index.js', 'utf8');
assert.ok(labIndex.includes('isPlayerMove') && labIndex.includes('MOVE_FORBIDDEN'));
const webHasEngine = webFiles.some(f => /manualSetLore|lorcanaRuntimeMoves|createSyntheticKernel/.test(readFileSync(f, 'utf8')));
assert.equal(webHasEngine, false, 'web app bundle contains engine code');
// Vendor source is unchanged since main (empty git diff); the deterministic kernel is 895,853 bytes /
// 895,847 UTF-16 characters (the refresh audit's RUN055 figure counted characters).
const kernelBuf = readFileSync('vendor/tcg-engines/dist/kernel.js'), kernelBytes = statSync('vendor/tcg-engines/dist/kernel.js').size;
assert.equal(kernelBytes, 895853, 'kernel size changed: ' + kernelBytes);
assert.equal(kernelBuf.toString('utf8').length, 895847);
const kernelSha = (await import('node:crypto')).createHash('sha256').update(kernelBuf).digest('hex');
const { execFileSync } = await import('node:child_process');
assert.equal(execFileSync('git', ['diff', '--stat', '9b9c8ac', 'HEAD', '--', 'vendor/', 'scripts/engine/']).toString().trim(), '', 'vendor/engine tooling changed since main');
// The server worker drains upstream console output and strips credential-like environment keys.
const exec = readFileSync('apps/match-service/dist/engine-executor.js', 'utf8');
assert.ok(/stdout\.resume\(\)/.test(exec) && /stderr\.resume\(\)/.test(exec) && /stdout:\s*true/.test(exec) && /stderr:\s*true/.test(exec));
assert.ok(exec.includes('password|secret|token|credential|private_key') && exec.includes('PG|POSTGRES|DATABASE'));
console.log(JSON.stringify({ browserOwners: browserOwners.length, browserImportsRefused: refused, serverKernelImportsRefused: serverRefused, webFilesScanned: webFiles.length, labFilesScanned: labFiles.length, serverOnlyMarkers: serverOnly.length, labWorkerBytes: Buffer.byteLength(lab), kernelBytes, kernelSha }));
console.log('PASS auditor PLAY-01 boundary and bundle probe: five browser/public owners refuse static/dynamic/re-export/type imports of db, match-service, adapter, service-runtime, pg, Node workers/crypto and relative paths to the new server sources; non-adapter server owners cannot reach the kernel/Lab/tests; web and Lab bundles carry no server-only PLAY-01 markers; Lab carries the policy guard; kernel unchanged');
